// P1 / WP2: arithmetic of the native car constants (see include/takedown/runtime/native_car_constants.hpp).
//
//   start_effect_quads   StartEffect (0x220040): the colour quads W+0..48, as the runtime's engine native computes them (host floats)
//   entry_constants      microprogram 0x16a: colour / ALPHA / flag table of one draw-list entry (hand-written from
//                        the microprogram listing, pc 362..416; VU0 float rules for the few multiplies and conversions)
//   light_matrix         microprogram 0xfb pc 0..250 and view_vectors pc 251..347: generated by symbolic execution
//                        (native_car_frame.inc) as straight-line float code

#include "takedown/runtime/native_car_constants.hpp"

#include "takedown/runtime/native_car_vu0_math.hpp"

#include <bit>
#include <cstdint>

namespace takedown::runtime::native_car {

using namespace vu;

#include "native_car_frame.inc"

void start_effect_quads(const std::uint32_t depth_scale, const std::uint32_t rate_scale, const std::uint32_t size_scale,
                        const float f12, const float f13, std::array<Qw, 4>& w) {
    // The runtime's StartEffect (engine native, render.cpp start_effect): host float products, rounded to nearest even (host_mul), where
    // the guest code would chop. 128 * f12 and 0.5 * size are exact either way.
    constexpr std::uint32_t kHalf = 0x3f000000U;    // 0.5F
    constexpr std::uint32_t kLarge = 0x43000000U;   // 128.0F
    const std::uint32_t alpha = bits(f12);
    const std::uint32_t bright = bits(f13);
    const std::uint32_t size = host_mul(size_scale, bright);
    const std::uint32_t half_size = host_mul(kHalf, size);
    w[0] = Qw{half_size, half_size, half_size, host_mul(depth_scale, alpha)};    // extent
    w[1] = Qw{0U, 0U, 0U, host_mul(rate_scale, alpha)};                          // rate
    w[2] = Qw{size, size, size, host_mul(kLarge, alpha)};                        // size
    w[3] = Qw{host_mul(size_scale, alpha), 0U, 0U, 0U};                          // spread (y, z: the part's f12 and light bits)
}

EntryConstants entry_constants(const EntryInput& in, const std::array<Qw, 4>& w) {
    // Registers of the program: c0 = VF6, c1 = VF7, env = VF8 (floats until the final VFTOI0), alpha1 = VF9 (integers).
    const float q0[4] = {flt(w[0][0]), flt(w[0][1]), flt(w[0][2]), flt(w[0][3])};
    const float q1[4] = {flt(w[1][0]), flt(w[1][1]), flt(w[1][2]), flt(w[1][3])};
    const float q2[4] = {flt(w[2][0]), flt(w[2][1]), flt(w[2][2]), flt(w[2][3])};
    const float spread = flt(w[3][0]);
    const float f12 = in.f12;

    const float alpha_scale = vmul(spread, f12);     // pc 363: VF5.x = spread * f12; 128.1 * f12 for a paint entry
    float c0[4], c1[4], env[4];
    std::uint32_t vi7 = 0U, vi8 = 0U;

    const bool lit = (in.light_bits & 0xffffU & in.material & 0xfcU) != 0U;
    if (lit) {
        // A light entry whose light is on: flat colours, no environment pass.
        for (int i = 0; i < 3; ++i) {
            c0[i] = 192.0F;
            c1[i] = 192.0F;
            env[i] = 128.0F;
        }
        c0[3] = 0.0F;
        c1[3] = 0.0F;
        env[3] = 0.0F;
        vi7 = 2U;
    } else {
        for (int i = 0; i < 4; ++i) {
            c1[i] = q2[i];
            c0[i] = (in.material & 0x300U) != 0U ? q0[i] : q1[i];     // glass uses the extent quad
        }
        env[0] = env[1] = env[2] = 128.0F;
        env[3] = vmul(1.0F, alpha_scale);
    }

    const float alpha = static_cast<float>(in.glass_alpha);        // VITOF0 of entry byte +13
    Qw alpha1{};
    if (in.slot == 4U) {
        // Glass slot 4: ALPHA_1 = (68, 0), the colour alphas carry the entry's own alpha, dark environment colour.
        c0[3] = vmul(1.0F, alpha);
        c1[3] = vmul(1.0F, alpha);
        env[0] = env[1] = env[2] = 20.0F;
        env[3] = 0.0F;
        alpha1 = Qw{68U, 0U, 66U, 0U};
        vi8 = 88U;
    } else {
        alpha1 = Qw{in.blend, ftoi0(vmul(alpha, f12)), 66U, 0U};
        const bool blend_bits = (in.blend & 0x30U) != 0U;
        if ((in.material & 2U) != 0U) {
            // Details: no environment alpha; opaque blend modes get alpha 128, the others none and no environment pass.
            vi8 = 106U;
            env[3] = 0.0F;
            if (!blend_bits) {
                c0[3] = vmul(1.0F, 128.0F);
                c1[3] = vmul(1.0F, 128.0F);
            } else {
                c0[3] = 0.0F;
                c1[3] = 0.0F;
                vi7 = 2U;
            }
        } else if (!blend_bits) {
            env[0] = env[1] = env[2] = 20.0F;
            c0[3] = vmul(1.0F, 128.0F);
            c1[3] = vmul(1.0F, 128.0F);
            vi8 = 88U;
        } else {
            vi8 = 84U;
        }
    }

    EntryConstants out;
    out.alpha1 = alpha1;
    out.alpha2 = Qw{vi8, 0U, 67U, 0U};
    out.colour0 = Qw{bits(c0[0]), bits(c0[1]), bits(c0[2]), bits(c0[3])};
    out.colour1 = Qw{bits(c1[0]), bits(c1[1]), bits(c1[2]), bits(c1[3])};
    out.env = Qw{ftoi0(env[0]), ftoi0(env[1]), ftoi0(env[2]), ftoi0(env[3])};
    out.flags = Qw{in.value, vi7, in.zone_count, 0U};
    out.reflective = (vi7 & 0xffffU) == 0U;
    return out;
}

} // namespace takedown::runtime::native_car
